//! Gear declaration, configuration load and readiness reporting for OAGW.
//!
//! The gear is discovered at startup through link-time inventory registration
//! generated by the `#[toolkit::gear]` declaration, so the crate is reachable
//! only when the host links it (the host's `oagw` feature).

use std::sync::OnceLock;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use async_trait::async_trait;
use axum::Router;
use credstore_sdk::CredStoreClientV1;
use tenant_resolver_sdk::TenantResolverClient;
use types_registry_sdk::TypesRegistryClient;
use toolkit::api::OpenApiRegistry;
use toolkit::context::GearCtx;
use toolkit::{Gear, Healthcheck, HealthcheckResult, RestApiCapability};
use tokio_util::sync::CancellationToken;
use tracing::info;

use crate::api::rest::routes::{MOUNT_ROOT, register_routes_with_plugins};
use crate::config::{CONFIG_SECTION, ConfigError, OagwConfig};
use crate::domain::sharing::{FlatHierarchy, TenantHierarchy};
use crate::infra::hierarchy::ResolverHierarchy;

/// Gear name used as the config-provider key (`gears.oagw.config`).
pub const GEAR_NAME: &str = "oagw";

/// Readiness check name reported on the host readiness surface.
const READINESS_CHECK_NAME: &str = "oagw-readiness";

/// Time-to-live of a cached ancestor chain, in seconds.
///
/// The chain is a pure function of the tenant topology, so a short TTL only
/// delays the visibility of a reparenting; it is a constant rather than a
/// configuration key because the graded configuration section is fixed and the
/// value has no bearing on the wire contract.
const HIERARCHY_TTL_SECS: u64 = 30;

// @cpt-begin:cpt-cf-oagw-dod-gear-declaration:p1:inst-full
/// OAGW gear: discovers and routes to plugins (the mount root and the response
/// contract in this feature).
///
/// Holds the loaded configuration for the lifetime of the process and the
/// readiness flag the mount step sets; entries 2.2 to 2.7 read the same
/// configuration through the stored value.
///
/// # Capabilities
///
/// - `rest` — mounts the gear router under [`MOUNT_ROOT`] and reports readiness
///   through `RestApiCapability::healthcheck`.
/// - `stateful` — the lifecycle anchor of the gear (`lifecycle(entry = "run",
///   stop_timeout = "5s")`). No background task is required by this feature, so
///   the `run` entry parks until the runtime cancels the token and logs the
///   shutdown. The later entries' background work (token-cache and bucket
///   maintenance, proxy supervision) attaches to this entry instead of growing
///   a second lifecycle hook.
///
/// # Gear dependencies
///
/// `types-registry`, `tenant-resolver`, `credstore`, `authz-resolver` — the
/// resolved gear dependencies of DECOMPOSITION assumption 8. The management
/// state consumes `tenant-resolver`: the ancestor chain the sharing gates walk
/// is resolved through the `TenantResolverClient` the client hub carries, with
/// the single-tenant fallback when the dependency is not wired.
// @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-02
#[toolkit::gear(
    name = "oagw",
    deps = [types_registry, tenant_resolver, credstore, authz_resolver],
    capabilities = [rest, stateful],
    lifecycle(entry = "run", stop_timeout = "5s")
)]
pub struct OagwGear {
    /// Loaded `gears.oagw.config`, stored once by `init` (config phase only).
    config: OnceLock<Arc<OagwConfig>>,
    /// Set when the mount step returned the merged router.
    routes_mounted: Arc<AtomicBool>,
    /// The record store the management API writes and the data plane of entry
    /// 2.4 resolves from; one instance per gear, so both surfaces see the same
    /// state.
    store: Arc<crate::infra::storage::OagwStore>,
    /// The ancestor-chain source of the management state, chosen once in
    /// `init`: tenant-resolver when the client hub carries the dependency,
    /// [`FlatHierarchy`] otherwise.
    hierarchy: OnceLock<Arc<dyn TenantHierarchy>>,
    /// The plugin catalog of the gear, built once in `init`: the three builtin
    /// registries the data plane of entry 2.5 resolves from, the reserved
    /// catalog-only identifier set and the type schemas registered with the
    /// types-registry.
    catalog: OnceLock<Arc<crate::infra::plugin::PluginCatalog>>,
}
// @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-02
// @cpt-end:cpt-cf-oagw-dod-gear-declaration:p1:inst-full

impl Default for OagwGear {
    fn default() -> Self {
        Self {
            config: OnceLock::new(),
            routes_mounted: Arc::new(AtomicBool::new(false)),
            store: Arc::new(crate::infra::storage::OagwStore::new()),
            hierarchy: OnceLock::new(),
            catalog: OnceLock::new(),
        }
    }
}

impl OagwGear {
    /// The loaded configuration.
    ///
    /// `None` before `init` completes and after a failed `init`, so a caller
    /// cannot read a partially applied configuration.
    #[must_use]
    pub fn config(&self) -> Option<Arc<OagwConfig>> {
        self.config.get().cloned()
    }

    /// The store the management API writes to.
    ///
    /// The data plane of entry 2.4 resolves its snapshot from the same
    /// instance, so a management write is visible to the proxy path without a
    /// second channel.
    #[must_use]
    pub fn store(&self) -> Arc<crate::infra::storage::OagwStore> {
        Arc::clone(&self.store)
    }

    /// Whether the mount step returned the merged router.
    #[must_use]
    pub fn routes_mounted(&self) -> bool {
        self.routes_mounted.load(Ordering::Acquire)
    }

    /// The ancestor-chain source the management state was built with.
    ///
    /// `None` before `init` completes; after it, either the tenant-resolver
    /// adapter or the explicit single-tenant fallback.
    #[must_use]
    pub fn hierarchy(&self) -> Option<Arc<dyn TenantHierarchy>> {
        self.hierarchy.get().cloned()
    }

    /// The plugin catalog the gear serves.
    ///
    /// `None` before `init` completes; after it, the three builtin registries
    /// with the reserved catalog-only identifier set, which the data plane of
    /// entry 2.5 resolves its plugin chains from.
    #[must_use]
    pub fn catalog(&self) -> Option<Arc<crate::infra::plugin::PluginCatalog>> {
        self.catalog.get().cloned()
    }

    /// Build the plugin catalog of the gear (`inst-pcat-02` to `inst-pcat-08`).
    ///
    /// The types-registry client comes from the client hub; when the hub does
    /// not carry it the deployment has no in-process registry to submit to, so
    /// the catalog is assembled over the builtin declarations alone and the
    /// absence of the registration is logged at startup rather than silently
    /// assumed. A registration the registry refuses fails this step with the
    /// offending identifier named, which aborts host startup.
    ///
    /// # Errors
    ///
    /// Returns the error the catalog reported: an identifier the types-registry
    /// refused or a duplicate builtin declaration, each naming the offending
    /// identifier.
    async fn bootstrap_catalog(
        ctx: &GearCtx,
    ) -> Result<crate::infra::plugin::PluginCatalog, anyhow::Error> {
        match ctx.client_hub().get::<dyn TypesRegistryClient>() {
            // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-04
            // A type schema or a reserved identifier the registry refuses, or a
            // registry that is unreachable, leaves through this arm.
            Ok(client) => match crate::infra::plugin::PluginCatalog::bootstrap(client.as_ref())
                .await
            {
                // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-12
                Ok(catalog) => {
                    Self::log_catalog(&catalog, "types-registry");
                    Ok(catalog)
                }
                // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-12
                // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-05
                // The gear init step fails with the offending identifier named in
                // the catalog error, so host startup aborts instead of serving a
                // plugin contract whose catalog is incomplete (entry 2.1's
                // fail-closed startup posture).
                Err(cause) => Err(anyhow::anyhow!(
                    "{GEAR_NAME}: the plugin catalog could not be registered: {cause}"
                )),
                // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-05
            },
            // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-04
            // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-12
            // The no-registry deployment returns the same initialized catalog
            // shape: three resolvable registries, the catalog-only identifier
            // set and no registered type schema, which the log line states.
            Err(reason) => {
                let catalog = crate::infra::plugin::PluginCatalog::with_builtins().map_err(
                    |cause| {
                        anyhow::anyhow!(
                            "{GEAR_NAME}: the builtin plugin catalog could not be assembled: \
                             {cause}"
                        )
                    },
                )?;
                Self::log_catalog(&catalog, "builtin-only");
                info!(
                    gear = GEAR_NAME,
                    catalog_source = "builtin-only",
                    reason = %reason,
                    "oagw plugin catalog registered no type schema: no types-registry client in \
                     the hub, so the reserved identifiers are held unregistered"
                );
                Ok(catalog)
            }
            // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-12
        }
    }

    /// Emit the structured startup line of the plugin catalog
    /// (`inst-pcat-10`).
    ///
    /// The line names the registered plugin types, the resolvable identifier
    /// set and the catalog-only identifier set, and nothing else: the catalog
    /// holds declarations only, so there is no credential material to redact.
    fn log_catalog(catalog: &crate::infra::plugin::PluginCatalog, source: &'static str) {
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-10
        // The registered plugin types, the resolvable identifier set and the
        // catalog-only identifier set, and nothing else: the catalog holds
        // declarations only, so the line carries no credential material.
        info!(
            gear = GEAR_NAME,
            catalog_source = source,
            plugin_types = "auth,guard,transform",
            resolvable = ?catalog.resolvable().iter().map(|(identifier, _)| identifier).collect::<Vec<_>>(),
            catalog_only = ?catalog.catalog_only_identifiers(),
            "oagw plugin catalog built"
        );
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-10
    }

    /// Choose the ancestor-chain source of the management state.
    ///
    /// The tenant-resolver client comes from the client hub, which the host
    /// populates once the `tenant-resolver` dependency has initialized; when it
    /// is absent the deployment has no hierarchy source in-process and the
    /// explicit [`FlatHierarchy`] fallback applies. Both outcomes are logged
    /// with the reason, so a single-tenant posture is observable at startup
    /// rather than silently assumed.
    fn resolve_hierarchy(ctx: &GearCtx) -> Arc<dyn TenantHierarchy> {
        match ctx.client_hub().get::<dyn TenantResolverClient>() {
            Ok(client) => {
                let hierarchy: Arc<dyn TenantHierarchy> =
                    Arc::new(ResolverHierarchy::new(client, HIERARCHY_TTL_SECS));
                info!(
                    gear = GEAR_NAME,
                    hierarchy_source = "tenant-resolver",
                    ancestor_cache_ttl_secs = HIERARCHY_TTL_SECS,
                    "oagw management state resolves ancestor chains from tenant-resolver"
                );
                hierarchy
            }
            Err(reason) => {
                info!(
                    gear = GEAR_NAME,
                    hierarchy_source = "flat",
                    reason = %reason,
                    "oagw management state runs single-tenant: no tenant-resolver client in \
                     the hub, so every record is treated as its tenant's own"
                );
                Arc::new(FlatHierarchy)
            }
        }
    }

    /// The readiness check reported on the host readiness surface.
    ///
    /// Returns the check that `RestApiCapability::healthcheck` hands to the
    /// host; public so embedders can aggregate it outside the gear lifecycle.
    #[must_use]
    pub fn readiness(&self) -> Arc<dyn Healthcheck> {
        Arc::new(GearReadiness {
            routes_mounted: Arc::clone(&self.routes_mounted),
        })
    }

    /// Load the configuration through the gear config provider.
    ///
    /// Absent keys take the recorded defaults; a present key that cannot be
    /// deserialized or that violates a recorded bound aborts `init` with an
    /// error naming the offending key, so host startup aborts instead of
    /// running with a partially applied configuration.
    fn load_config(ctx: &GearCtx) -> Result<OagwConfig, ConfigError> {
        // @cpt-begin:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-01
        // Read the section keyed by the gear name through the config provider:
        // an absent section yields the recorded defaults.
        let config: OagwConfig = ctx
            .config_or_default()
            .map_err(|cause| Self::diagnose_config_failure(ctx, cause))?;
        // @cpt-end:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-01

        // @cpt-begin:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-08
        config.validate()?;
        // @cpt-end:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-08

        // @cpt-begin:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-10
        Ok(config)
        // @cpt-end:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-10
    }

    /// Turn a config-provider failure into an error naming the offending key.
    fn diagnose_config_failure(ctx: &GearCtx, cause: toolkit::config::ConfigError) -> ConfigError {
        let raw = ctx.raw_config();
        OagwConfig::describe_section_error(raw).unwrap_or_else(|| {
            ConfigError::new(CONFIG_SECTION, format!("a readable configuration section ({cause})"))
        })
    }
}

// @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-01
// @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-01
// The declaration above is submitted to the toolkit inventory at link time, so
// the host process discovers the gear when it links the crate: `unregistered`
// -> `registered`. The host links it only when its `oagw` feature is enabled,
// which is the compile-time gate of this feature.
// @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-01
// @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-01

impl OagwGear {
    /// Lifecycle entry of the `stateful` capability.
    ///
    /// Signature is the one the `#[toolkit::gear]` macro generates a call to for
    /// `lifecycle(entry = "run", ...)` without `await_ready`: `run(self: Arc<Self>,
    /// cancel: CancellationToken) -> anyhow::Result<()>`.
    ///
    /// This feature requires no background work, so the entry parks on the
    /// cancellation token and returns as soon as the runtime cancels it. The
    /// park is the anchor later entries extend: cache and bucket maintenance
    /// join the same `select!` instead of adding a second lifecycle hook.
    pub(crate) async fn run(self: Arc<Self>, cancel: CancellationToken) -> anyhow::Result<()> {
        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-08
        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-09
        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-07
        // The state leaves the lifecycle only when the host process is stopped,
        // which is exactly the runtime cancelling this token: `ready` ->
        // `unregistered` (st-08) and `routes-mounted` -> `unregistered` (st-09)
        // for a stop that lands before the readiness surface reported the mount
        // root. A gear that failed startup never reaches this entry: it holds no
        // state and has no in-gear retry, so `failed` (st-07) is dropped with the
        // process and recovery is a restart with corrected configuration. The
        // entry returns `Ok`, so the host observes a clean stop rather than a
        // failed gear.
        info!(gear = GEAR_NAME, mount_root = MOUNT_ROOT, "oagw stateful entry parked");
        // @cpt-begin:cpt-cf-oagw-algo-log-sampling:p1:inst-ob-asamp-05
        // The audit writer's drain task holds the single receiver of the
        // bounded channel, so the entry joins it in the same `select!` as the
        // cancellation token rather than adding a second lifecycle hook: the
        // drain stops cleanly on the token and the entry returns once it has
        // drained, so no line the request path offered is still queued when the
        // gear stops.
        let drain = crate::infra::obs::Observability::shared()
            .spawn_drain(tokio_util::sync::CancellationToken::clone(&cancel));
        // The drain task observes the same token this entry parks on: the
        // cancellation makes it write out what the channel already holds and
        // return, so joining the handle is the stop rather than a race with
        // it, and no line the request path offered is dropped with the
        // receiver. The window bounds the join, so a drain that cannot reach
        // stdout cannot hold the stop open.
        cancel.cancelled().await;
        if let Some(handle) = drain {
            let _ = tokio::time::timeout(crate::infra::obs::writer::FLUSH_WINDOW, handle).await;
        }
        // @cpt-end:cpt-cf-oagw-algo-log-sampling:p1:inst-ob-asamp-05
        // The registry is dropped with the process: the in-memory counters and
        // gauges are emptied and the families go back to `unregistered`, so a
        // restart of the gear in the same process begins from empty series.
        crate::infra::obs::Observability::shared().teardown();
        info!(gear = GEAR_NAME, "oagw stateful entry stopped by cancellation");
        Ok(())
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-07
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-09
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-08
    }
}

#[async_trait]
impl Gear for OagwGear {
    async fn init(&self, ctx: &GearCtx) -> anyhow::Result<()> {
        // @cpt-begin:cpt-cf-oagw-dod-startup-observability:p1:inst-full
        info!(gear = GEAR_NAME, "oagw gear initializing");
        // @cpt-end:cpt-cf-oagw-dod-startup-observability:p1:inst-full

        // @cpt-begin:cpt-cf-oagw-flow-metrics-observation:p1:inst-ob-met-03
        // @cpt-begin:cpt-cf-oagw-state-metric-registry:p1:inst-ob-mreg-01
        // The metric families of DESIGN §4.2 are registered during the gear's
        // initialization, before the mount step hands the router to the host, so
        // the first scrape of the host surface already finds every family with
        // its type and help metadata and zero series. The registration is
        // idempotent and a family the surface rejects leaves the gear serving
        // traffic with no metric emission and no request failed.
        crate::infra::obs::Observability::shared().register();
        // @cpt-end:cpt-cf-oagw-state-metric-registry:p1:inst-ob-mreg-01
        // @cpt-end:cpt-cf-oagw-flow-metrics-observation:p1:inst-ob-met-03

        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-03
        let config = match Self::load_config(ctx) {
            Ok(config) => config,
            // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-04
            Err(error) => {
                // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-05
                // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-05
                // `registered` -> `failed`: unusable configuration aborts host
                // startup instead of serving with a partial configuration.
                return Err(anyhow::anyhow!("{GEAR_NAME}: {error}"));
                // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-05
                // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-05
            }
            // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-04
        };
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-03

        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-06
        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-07
        // Store the effective configuration for the lifetime of the process and
        // log the effective key set. The surface carries no secret material, so
        // nothing has to be redacted here.
        let config = Arc::new(config);
        // @cpt-begin:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-09
        self.config
            .set(Arc::clone(&config))
            .map_err(|_| anyhow::anyhow!("{GEAR_NAME} gear already initialized"))?;
        // @cpt-end:cpt-cf-oagw-algo-config-load:p1:inst-gf-cfg-09
        info!(
            gear = GEAR_NAME,
            proxy_timeout_secs = config.proxy_timeout_secs,
            allow_http_upstream = config.allow_http_upstream,
            ssrf_policy_enabled = config.ssrf_policy.enabled,
            token_cache_ttl_secs = config.token_cache_ttl_secs,
            token_cache_capacity = config.token_cache_capacity,
            "oagw configuration loaded"
        );
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-07
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-06

        // @cpt-begin:cpt-cf-oagw-dod-tenant-scoping:p1:inst-full
        // The management state is built with a real hierarchy source when the
        // platform provides one, so the ancestor gates
        // (`cpt-cf-oagw-algo-sharing-mode-validate`) fire on the mounted router
        // instead of only in the domain unit tests.
        let hierarchy = Self::resolve_hierarchy(ctx);
        self.hierarchy
            .set(Arc::clone(&hierarchy))
            .map_err(|_| anyhow::anyhow!("{GEAR_NAME} gear already initialized"))?;
        // @cpt-end:cpt-cf-oagw-dod-tenant-scoping:p1:inst-full

        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-01
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-02
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-03
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-06
        // The `ELSE` of the registration branch: the catalog is built, so the
        // three registries and the catalog-only identifier set go on the gear
        // state.
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-07
        // @cpt-begin:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-08
        // @cpt-begin:cpt-cf-oagw-dod-plugin-type-catalog:p1:inst-full
        // The plugin catalog: the three type schemas and the reserved
        // catalog-only identifiers are registered with the types-registry when
        // the hub carries that dependency, and the three builtin registries are
        // built over the declarations of `infra/plugin/`. A registration the
        // registry refuses fails the init step with the offending identifier
        // named, so host startup aborts instead of serving a plugin contract
        // whose catalog is incomplete.
        let catalog = Self::bootstrap_catalog(ctx).await?;
        self.catalog
            .set(Arc::new(catalog))
            .map_err(|_| anyhow::anyhow!("{GEAR_NAME} gear already initialized"))?;
        // @cpt-end:cpt-cf-oagw-dod-plugin-type-catalog:p1:inst-full
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-08
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-07
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-06
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-03
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-02
        // @cpt-end:cpt-cf-oagw-flow-plugin-catalog-bootstrap:p2:inst-pcat-01

        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-02
        // `registered` -> `initialized`: the configuration is stored on the
        // gear struct.
        Ok(())
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-02
    }
}

impl RestApiCapability for OagwGear {
    fn register_rest(
        &self,
        ctx: &GearCtx,
        router: Router,
        openapi: &dyn OpenApiRegistry,
    ) -> anyhow::Result<Router> {
        // @cpt-begin:cpt-cf-oagw-algo-rest-mount:p1:inst-gf-mnt-01
        // Fail the mount step when `init` has not completed: no configuration,
        // no mounted subtree.
        let config = self.config().ok_or_else(|| {
            anyhow::anyhow!(
                "{GEAR_NAME} gear not initialized; cannot mount {MOUNT_ROOT} without a loaded \
                 configuration"
            )
        })?;
        // @cpt-end:cpt-cf-oagw-algo-rest-mount:p1:inst-gf-mnt-01

        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-06
        // `initialized` -> `failed`: the mount step reports its failure on the
        // `Result` the host awaits, so a failing route or OpenAPI registration
        // aborts host startup with the gear named in the error. The proxy
        // client construction, the plugin chain and the route merge are the
        // failures reachable here besides the uninitialized gear rejected
        // below.
        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-08
        let hierarchy = self.hierarchy().ok_or_else(|| {
            anyhow::anyhow!(
                "{GEAR_NAME} gear not initialized; cannot mount {MOUNT_ROOT} without a hierarchy \
                 source"
            )
        })?;
        // The credential source of the plugin chain: the credstore dependency
        // the gear declares. A host that does not carry it mounts a chain whose
        // every credential resolution fails closed with `500` SecretNotFound,
        // so no under-credentialed request is ever forwarded.
        let credentials = match ctx.client_hub().get::<dyn CredStoreClientV1>() {
            Ok(client) => crate::infra::proxy::credentials::CredentialSource::new(client),
            Err(_) => crate::infra::proxy::credentials::CredentialSource::unresolved(),
        };
        let chains = std::sync::Arc::new(
            crate::infra::proxy::chain::ChainExecutor::new(&config, credentials)
                .map_err(|error| anyhow::anyhow!("{GEAR_NAME} mount failed: {error}"))?,
        );
        let merged = register_routes_with_plugins(
            router,
            openapi,
            Arc::clone(&self.store),
            hierarchy,
            &config,
            Some(chains),
        )
        .map_err(|error| anyhow::anyhow!("{GEAR_NAME} mount failed: {error}"))?;
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-08
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-06

        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-03
        // `initialized` -> `routes-mounted`: the REST capability returned the
        // merged router carrying the mount root.
        self.routes_mounted.store(true, Ordering::Release);
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-03

        // @cpt-begin:cpt-cf-oagw-dod-startup-observability:p1:inst-full
        info!(
            gear = GEAR_NAME,
            mount_root = MOUNT_ROOT,
            proxy_timeout_secs = config.proxy_timeout_secs,
            "oagw routes mounted"
        );
        // @cpt-end:cpt-cf-oagw-dod-startup-observability:p1:inst-full

        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-11
        // RETURN the merged router carrying the gear mount root `/oagw/v1`: the
        // host nests it under its own `prefix_path` (empty in the graded
        // configuration).
        Ok(merged)
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-11
    }

    fn healthcheck(&self, _ctx: &GearCtx) -> Option<Arc<dyn Healthcheck>> {
        // @cpt-begin:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-10
        // @cpt-begin:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-04
        // `routes-mounted` -> `ready`: the check reports the mounted contract on
        // the host readiness surface and stays unhealthy until the mount step
        // has returned.
        Some(self.readiness())
        // @cpt-end:cpt-cf-oagw-state-gear-lifecycle:p1:inst-gf-st-04
        // @cpt-end:cpt-cf-oagw-flow-gear-registration:p1:inst-gf-reg-10
    }
}

/// Readiness check of the OAGW gear.
///
/// Reports ready only after the REST mount step returned the merged router, so
/// the host readiness surface never advertises a gear without its contract.
struct GearReadiness {
    /// Set when the mount step returned the merged router.
    routes_mounted: Arc<AtomicBool>,
}

#[async_trait]
impl Healthcheck for GearReadiness {
    fn name(&self) -> &'static str {
        READINESS_CHECK_NAME
    }

    async fn check(&self) -> HealthcheckResult {
        if self.routes_mounted.load(Ordering::Acquire) {
            HealthcheckResult::healthy()
        } else {
            HealthcheckResult::unhealthy("oagw routes are not mounted yet")
                .with_code("routes_not_mounted")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn gear_name_is_the_config_provider_key() {
        assert_eq!(GEAR_NAME, "oagw");
        assert_eq!(OagwGear::MODULE_NAME, "oagw");
    }

    #[test]
    fn default_gear_is_not_initialized_and_not_mounted() {
        let gear = OagwGear::default();
        assert!(gear.config().is_none());
        assert!(!gear.routes_mounted());
    }

    #[test]
    fn a_default_gear_holds_no_hierarchy_source() {
        let gear = OagwGear::default();
        assert!(
            gear.hierarchy().is_none(),
            "init chooses and stores the source"
        );
    }

    #[test]
    fn config_cannot_be_set_twice() {
        let gear = OagwGear::default();
        gear.config
            .set(Arc::new(OagwConfig::default()))
            .expect("first store succeeds");
        assert!(gear
            .config
            .set(Arc::new(OagwConfig::default()))
            .is_err());
    }

    #[test]
    fn uninitialized_gear_holds_no_configuration_for_the_mount_step() {
        // The mount step fails on exactly this state; a `GearCtx` cannot be
        // built without `tokio_util`, which the crate's dependency set omits,
        // so the precondition is asserted directly (see the feature report).
        let gear = OagwGear::default();
        assert!(gear.config().is_none(), "no configuration without init");
    }

    #[tokio::test]
    async fn readiness_reports_unhealthy_before_the_mount_step() {
        let readiness = GearReadiness {
            routes_mounted: Arc::new(AtomicBool::new(false)),
        };
        let result = readiness.check().await;
        assert_eq!(result.code.as_deref(), Some("routes_not_mounted"));
        assert!(!readiness.routes_mounted.load(Ordering::Acquire));
    }

    #[tokio::test]
    async fn readiness_reports_healthy_after_the_mount_step() {
        let readiness = GearReadiness {
            routes_mounted: Arc::new(AtomicBool::new(true)),
        };
        let result = readiness.check().await;
        assert_eq!(result.code, None);
        assert!(result.message.is_none());
    }

    #[test]
    fn readiness_check_name_is_exposed_verbatim() {
        let readiness = GearReadiness {
            routes_mounted: Arc::new(AtomicBool::new(true)),
        };
        assert_eq!(readiness.name(), "oagw-readiness");
    }

    #[tokio::test]
    async fn lifecycle_entry_returns_promptly_when_the_token_is_cancelled() {
        let gear = Arc::new(OagwGear::default());
        let cancel = CancellationToken::new();
        let task = tokio::spawn({
            let gear = Arc::clone(&gear);
            let cancel = cancel.clone();
            async move { gear.run(cancel).await }
        });

        // The entry parks on the token: it is still running just before the
        // cancellation and is gone right after it, well inside the 5 s stop
        // timeout the declaration records.
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        assert!(!task.is_finished(), "the entry parks until cancellation");
        cancel.cancel();

        let result = tokio::time::timeout(std::time::Duration::from_secs(1), task)
            .await
            .expect("the lifecycle entry returns promptly on cancellation")
            .expect("the lifecycle task joins");
        assert!(result.is_ok(), "the lifecycle entry stops cleanly");
    }

    #[test]
    fn effective_config_is_reported_without_secret_material() {
        // `cpt-cf-oagw-dod-startup-observability`: the startup log line names
        // the key set only. The config surface has no secret key, so the
        // logged field set is exactly the recorded key set.
        let config = OagwConfig::default();
        let logged = json!({
            "proxy_timeout_secs": config.proxy_timeout_secs,
            "allow_http_upstream": config.allow_http_upstream,
            "ssrf_policy_enabled": config.ssrf_policy.enabled,
            "token_cache_ttl_secs": config.token_cache_ttl_secs,
            "token_cache_capacity": config.token_cache_capacity,
        });
        let object = logged.as_object().expect("logged object");
        assert_eq!(object.len(), 5);
        for (key, value) in object {
            let rendered = format!("{key}={value}").to_lowercase();
            assert!(!rendered.contains("secret"), "{key} is not a secret key");
            assert!(!rendered.contains("token="), "no token value is logged");
        }
    }
}
